import logging
import telnetlib
import socket
import time


class TelnetClient(object):
    """Class to control telnet connection to JFW attenuator"""

    # pylint: disable=broad-except, logging-not-lazy, bare-except

    def __init__(self):
        logging.basicConfig(format="%(asctime)s %(levelname)s %(message)s", level=logging.DEBUG)
        self.host = None
        self.client = None
        self.port = None

    def connect(self, host, port):
        """
        Establish telnet connection
        :param host: telnet host
        :param port: telnet port
        """
        self.host = host
        self.port = port
        self._establish_connection()

    def _establish_connection(self):
        logging.info('Establishing connection to attenuator.')
        for ii in range(2):
            try:
                self.client = telnetlib.Telnet(self.host, int(self.port))
                logging.debug(self.client.read_very_eager())
                logging.info('Connection established.')
                break
            except socket.error as e:
                logging.info('Exception occured: {}'.format(str(e)))
                logging.info("Telnet trying to reconnect: " + str(ii))
                time.sleep(5)
        else:
            raise Exception("Cannot establish connection to attenuator: {}".format(self.host))

    def write_command(self, command):
        """
        Write telnet command
        :param command:
        :return:
        """
        try:
            self._write(command)
        except Exception as e:
            try:
                logging.debug("Exception during sending command: {}".format(str(e)))
                logging.debug('Trying to reconnect ...')
                self._establish_connection()
                self._write(command)
            except:
                logging.debug("Exception during sending command: {}".format(str(e)))
                logging.exception(str(e))
                raise

    def read_command(self, command, read_method='eager'):
        """
        Read telnet command
        :param command:
        """
        try:
            return self._write_and_read(command, read_method)
        except Exception as e:
            try:
                logging.debug("Exception during sending command: {}".format(str(e)))
                self._establish_connection()
                return self._write_and_read(command, read_method)
            except:
                logging.exception("general error in send command")
                logging.exception(str(e))
                raise

    def _write(self, command):
        output = ""
        cmd_to_write = command + "\r\n"
        self.client.write(cmd_to_write.encode())
        output += command + "\r\n"
        time.sleep(0.05)
        return output

    def _write_and_read(self, command, read_method):
        output = ""
        cmd_to_write = command + "\r\n"
        self.client.write(cmd_to_write.encode())
        output += command + "\r\n"
        time.sleep(0.05)
        if read_method == 'eager':
            read_output = str(self.client.read_very_eager())
        if read_method == 'until':
            read_output = str(self.client.read_until("\r\n", 2))
        output += read_output
        time.sleep(0.05)
        return output

    def close_connection(self):
        """Close telnet connection"""
        try:
            if hasattr(self.client, "close"):
                self.client.close()
        except Exception as e:
            logging.exception("ex. in client.close(): {}".format(e))

    def __del__(self):
        self.close_connection()
